function testCurveLength (curveMetrics: Readonly<CurveAndMetrics>, expectedValue: Readonly<number>) {
  assert.strictEqual(curveMetrics.length, expectedValue, `Expected length should be ${expectedValue}, encountered ${curveMetrics.length}`)
}

function testCurveAverage (curveMetrics: Readonly<CurveAndMetrics>, expectedValue: Readonly<number>) {
  assert.strictEqual(curveMetrics.average, expectedValue, `Expected average should be ${expectedValue}, encountered ${curveMetrics.average}`)
}

function testCurvePeak (curveMetrics: Readonly<CurveAndMetrics>, expectedValue: Readonly<number>) {
  assert.strictEqual(curveMetrics.peak, expectedValue, `Expected peak should be ${expectedValue}, encountered ${curveMetrics.peak}`)
}

function testCurvePeakPosition (curveMetrics: Readonly<CurveAndMetrics>, expectedValue: Readonly<number>) {
  assert.strictEqual(curveMetrics.peakNormalizedPosition, expectedValue, `Expected peakNormalizedPosition should be ${expectedValue}, encountered ${curveMetrics.peakNormalizedPosition}`)
}

function testCurve (curveMetrics: Readonly<CurveAndMetrics>, expectedValue: Readonly<number>) {
  assert.strictEqual(curveMetrics.curve.toString(), expectedValue.toString(), `Expected length should be ${expectedValue}, encountered ${curveMetrics.length}`)
}
